$ErrorActionPreference='Stop';$root=Join-Path $PSScriptRoot '..\src\WAID.Desktop';$main=Get-Content -Raw (Join-Path $root 'MainWindow.xaml');@('NavDashboard','NavDrivers','NavBoot','NavUpdates','NavStorage','NavDiagnosis','NavHealth','NavOperations','NavRepairs','NavHistory','NavAudit','NavPlugins')|ForEach-Object{if($main-notmatch$_){throw "Missing automation id $_"}};$app=Get-Content -Raw (Join-Path $root 'App.xaml.cs');if($app-notmatch'StartupRecoveryTitle'){throw 'Missing startup recovery automation id'};$settings=Get-Content -Raw (Join-Path $root 'Views\SettingsPage.xaml');@('SettingsSearch','ImportSettingsProfile','ExportSettingsProfile','ResetSettings','RefreshDatabaseHealth','BackupDatabase','RestoreDatabase')|ForEach-Object{if($settings-notmatch$_){throw "Missing settings automation id $_"}};$dashboard=Get-Content -Raw (Join-Path $root 'Views\DashboardPage.xaml');if($dashboard-notmatch'ScannerPlan'){throw 'Missing scanner plan automation id'};$drivers=Get-Content -Raw (Join-Path $root 'Views\DriverHealthPage.xaml');@('DriverHealthTitle','AnalyzeDriversButton','DriverFindingFilter')|ForEach-Object{if($drivers-notmatch$_){throw "Missing driver accessibility id $_"}};$boot=Get-Content -Raw (Join-Path $root 'Views\BootHealthPage.xaml');@('BootHealthTitle','AnalyzeStartupButton')|ForEach-Object{if($boot-notmatch$_){throw "Missing boot accessibility id $_"}};$updates=Get-Content -Raw (Join-Path $root 'Views\UpdateHealthPage.xaml');@('UpdateHealthTitle','AnalyzeUpdatesButton')|ForEach-Object{if($updates-notmatch$_){throw "Missing update accessibility id $_"}};$storage=Get-Content -Raw (Join-Path $root 'Views\StorageCenterPage.xaml');@('StorageCenterTitle','AnalyzeStorageButton')|ForEach-Object{if($storage-notmatch$_){throw "Missing storage accessibility id $_"}};Get-ChildItem (Join-Path $root 'Views') -Filter '*.xaml'|ForEach-Object{[xml](Get-Content -Raw $_.FullName)|Out-Null};Write-Host 'Accessibility navigation and recovery smoke checks passed.'
